def factorial(number):
    result = 1
    for value in range(2, number + 1):
        result *= value
    return result

def multiply_list(numbers):
    result = 1
    for number in numbers:
        result *= number
    return result

def remove_duplicates(values):
    seen = []
    for value in values:
        if value not in seen:
            seen.append(value)
    return seen

def swap_first_last(values):
    if len(values) < 2:
        return list(values)
    swapped = list(values)
    swapped[0], swapped[-1] = swapped[-1], swapped[0]
    return swapped

def find_index(values, target):
    if target in values:
        return values.index(target)
    return -1

def circle_area(radius):
    import math

    return math.pi * radius * radius

def digit_sum(number):
    total = 0
    for digit in str(abs(number)):
        total += int(digit)
    return total

def is_leap_year(year):
    if year % 400 == 0:
        return True
    if year % 100 == 0:
        return False
    return year % 4 == 0

def grade(score):
    if score >= 50:
        return "pass"
    return "fail"

def gcd(a, b):
    import math

    return math.gcd(a, b)
